import subprocess, sys, json

BIN = "/tmp/orig-srgn"

def probe(lang, node):
    q = "(%s) @x" % node
    p = subprocess.run([BIN, "--%s-query" % lang, q,
                        "--stdin-detection", "force-readable",
                        "--stdout-detection", "force-pipe"],
                       stdin=subprocess.DEVNULL,
                       capture_output=True, text=True)
    err = (p.stdout + p.stderr).strip()
    if "Invalid node type" in err:
        return ("BAD", err)
    if "Error occurred while creating a tree-sitter query" in err:
        return ("OTHER", err)
    return ("OK", err)

def run(lang, cands):
    ok, bad, other = [], [], []
    for c in cands:
        st, err = probe(lang, c)
        if st == "OK": ok.append(c)
        elif st == "BAD": bad.append(c)
        else: other.append((c, err))
    return ok, bad, other

if __name__ == "__main__":
    lang = sys.argv[1]
    cands = [l.strip() for l in open(sys.argv[2]) if l.strip()]
    ok, bad, other = run(lang, cands)
    print("### %s: %d/%d valid" % (lang, len(ok), len(cands)))
    print("VALID:", " ".join(ok))
    print()
    print("INVALID:", " ".join(bad))
    if other:
        print()
        print("OTHER:", other)
PYEOF
